entries[359235] = { ["name"] = "Rückgewinnungsform", ["text"] = "Wirken in 6 sek.\nHalondrus verankert sich auf einem Vorkommen von ' Ephemerer Riss ' und fügt allen Spielercharakteren jedes Mal, wenn er ein Bein in den Sand gräbt, 15664 körperlichen Schaden zu.\n\nAktiviert ' Ewigkeitsantrieb '." }
