entries[359315] = { ["name"] = "Seelenflamme", ["text"] = "100 Meter Reichweite\nSofort\nErhöht den Feuerschaden von Spielercharakteren in der Nähe 3 Min. lang um 20%. Dieser Effekt ist stapelbar." }
entries[359317] = { ["name"] = "Wen Lo, die Seele des Flusses", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Flüsse Pandarias sind unberechenbar, so wie es auch Wen Lo ist. Bisweilen sind sie ruhig und bringen Wasser für die Felder, doch können sie auch über die Ufer treten und Verderben bringen. Wen Lo erinnert uns daran, dass wir an den Herausforderungen des Lebens wachsen müssen.\"\nWoW-Shop" }
entries[359318] = { ["name"] = "Segelnder Zauberfoliant", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"In den vergessenen Tiefen der Bibliothek von Dalaran fand man diesen übergroßen Folianten, der wie verrückt durch den Raum flatterte. Öffnet dieses mit arkaner Energie erfüllte Buch und fliegt in ein magisches Abenteuer.\"\nErfolg:\nDie Tour de Turm\nKategorie:\nZeitwanderung" }
entries[359319] = { ["name"] = "Quest abgeschlossen: Täglich" }
entries[359320] = { ["name"] = "Kill Credit: Rare" }
entries[359326] = { ["name"] = "Finsteres Omen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchicksalsschreiber Roh-Kalo bindet mehrere Spielercharaktere an Runen auf dem Webstuhl der Schicksale.\n\nFalls ein gebundener Spielercharakter nach 9 Sek. seine zugewiesene Rune berührt, fügt der Schicksalsschreiber allen Spielercharakteren in der Rune 19968 Schattenschaden zu.\n\nWenn eine Rune abläuft, ohne dass sich der daran gebundene Spielercharakter in ihr befindet, fügt der Schicksalsschreiber allen Spielercharakteren 107829 Schattenschaden zu." }
entries[359333] = { ["name"] = "Leerer Steinsuppenkessel", ["text"] = "Wirken in 3 sek.\nReagenzien:\nLeerer Kessel , Verdunkelter Stein , Erfrischendes Quellwasser (5)\nVerkäufer:\nOlea Manu\nZone:\nZereth Mortis\nKosten:\n25\n\nBenutzen: Richtet einen Kessel Steinsuppe her, der mit köstlichen Zutaten gefüllt werden kann. Stellt die Suppe fertig, damit sie bis zu 70 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nDie fertige Suppe stellt im Verlauf von 20 Sek. 173077 Gesundheit und 138461 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 53 erhöht.\n60" }
