entries[359336] = { ["name"] = "Steinsuppenkessel vorbereiten", ["text"] = "5 Meter Reichweite\nWirken in 1 sek.\nRichtet einen Kessel Steinsuppe her, der mit köstlichen Zutaten gefüllt werden kann. Stellt die Suppe fertig, damit sie bis zu 70 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nDie fertige Suppe stellt im Verlauf von 20 Sek. 173077 Gesundheit und 138461 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 53 erhöht." }
entries[359337] = { ["name"] = "Dekonstruktionsstern", ["text"] = "30\n- 40\nMeter Reichweite\nWirken in 3 sek.\nFügt allen Gegnern innerhalb von 30 Metern um das Ziel kosmischen Schaden sowie alle 5.2 Sek. zusätzlichen kosmischen Schaden zu." }
