entries[359361] = { ["name"] = "Bansheegestalt", ["text"] = "100 Meter Reichweite\nWirken in 4 sek.\nSylvanas verwandelt sich in eine Banshee!" }
entries[359362] = { ["name"] = "Reparieren", ["text"] = "Kanalisiert (Wirken in 0 sek.)\nSolange Gallywix' Mech Azerittreibstoff besitzt, stellt er einen Teil seiner Gesundheit wieder her, sobald seine Gesundheit auf einen kritischen Wert verringert wird." }
entries[359364] = { ["name"] = "Bronzeflügelvespid", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Bronzeflügelvespiden sind ein Ergebnis des Versuchs, eine Vespidenkönigin ohne weitere Mitglieder eines neuen Schwarms zu synthetisieren. Obwohl bisher noch kein Sterblicher herausgefunden hat, wie man einen Stock synthetisiert, stellen die Bronzeflügel selbst in ihrem aktuellen Zustand verlässliche Reittiere dar.\"\nBeruf:\nProtoformsynthese" }
entries[359366] = { ["name"] = "Summ", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Summ summ summ, summ summ! Summ summ summ summ summ. Summ summ summ, summ summ summ.\"\nBeruf:\nProtoformsynthese" }
entries[359367] = { ["name"] = "Geschmiedeter Tückenflügler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Es gibt kaum etwas, das einen das Leben so sehr spüren lässt wie ein Ritt durch das Reich des Todes auf dem Rücken eines Wesens, das einen hasst.\"\nBeruf:\nProtoformsynthese" }
entries[359372] = { ["name"] = "Schlundadaptierter Raptora", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Seit dem Übergriff des Kerkermeisters sind neue Raptoras durch Zereth Mortis synthetisiert worden, die dem verderbenden Einfluss des Schlunds widerstehen können.\"\nBeruf:\nProtoformsynthese" }
entries[359373] = { ["name"] = "Raptorasturzflieger", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Der Raptorasturzflieger ist eine der grausamsten Ausprägungen dieser Art, perfekt an seine ökologische Nische angepasst. Die Sturzflieger, die heutzutage synthetisiert werden, benötigen keine weitere Anpassungen und sind identisch mit denen, die in der Vergangenheit erschaffen wurden.\"\nBeruf:\nProtoformsynthese" }
entries[359374] = { ["name"] = "Negationsschutz", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek.\nHüllt das Ziel in einen Schild, der Angreifern 10 Sek. lang kosmischen Schaden zufügt.\n(250ms Abklingzeit)" }
entries[359375] = { ["name"] = "Negationsschutz", ["text"] = "50 Meter Reichweite\nSofort\nVerursacht kosmischen Schaden." }
entries[359376] = { ["name"] = "Bronzener Helicid", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Einige Heliciden von Zereth Mortis haben von Natur aus seltsam metallische Schneckenhäuser. Sie sind üblicherweise bronzefarben, und ihr Metall unterscheidet sich nicht von dem, mit dem sogar Anfänger unter den Minenarbeitern umgehen können, mit der Einschränkung, dass die Konstruktion dieser Kreatur die Fähigkeiten von Anfängern mehr als überfordern würde.\"\nBeruf:\nProtoformsynthese" }
entries[359377] = { ["name"] = "Gescheiterter Flitzopodenprototyp", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese Kreatur ist nicht von den Ersten entworfen worden, sondern stattdessen von einem unbekannten Wesen in dem Versuch, einen sehr schnellen Läufer zu kreieren. Es blieb bei dem Versuch, da dieses Reittier doch sehr langsam ist.\"\nBeruf:\nProtoformsynthese" }
entries[359378] = { ["name"] = "Scharlachroter Helicid", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die ungewöhnliche rötliche Färbung dieses Heliciden ist eindeutig beabsichtigt, und der einzige andere Unterschied zwischen diesem und anderen Heliciden ist das ungewöhnliche Fehlen von Schleim.\"\nBeruf:\nProtoformsynthese" }
entries[359379] = { ["name"] = "Schimmernder Aurelid", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Obschon er einst geschaffen wurde, das Mausoleum der Ersten zu verteidigen, folgt er jetzt nach der Erfüllung seiner Primärfunktion gehorsam Euren Befehlen.\"\nErfolg:\nRuhm des Mausoleumsschlachtzüglers\nKategorie:\nDungeons & Schlachtzüge" }
entries[359380] = { ["name"] = "Tiefenpirscher", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ein paar dieser Quallen wurden in Zereth Mortis gewildert und sind über Bord gegangen, als das Schiff der Wilderer sank. Sie haben in den Tiefen des Großen Meeres ein neues Zuhause gefunden.\"\nHandelsposten" }
entries[359381] = { ["name"] = "Kryptischer Aurelid", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Chiffren der Ersten entziehen sich dem Verständnis der Sterblichen. Ein seltsamer Effekt dieser Sprache ist, dass sich einige Aureliden aus unbekannten Gründen zu jenen Sterblichen hingezogen fühlen, die danach streben, das Mysterium zu ergründen.\"\nErfolg:\nVon A bis Zereth\nKategorie:\nSchattenlande" }
entries[359383] = { ["name"] = "Sofortige Auslöschung" }
entries[359384] = { ["name"] = "Brons Aufruf zum Handeln", ["text"] = "Sofort\nNach dem Einsatz von 75 Schadens- oder Heilzaubern und -fähigkeiten beschwört Euer nächster Zauber oder Eure nächste Fähigkeit Bron. Bron stößt Gegner bei seiner Ankunft zurück und greift 30 Sek. lang Eure Ziele an oder heilt sie." }
entries[359386] = { ["name"] = "Schlundgebundene Barriere" }
entries[359387] = { ["name"] = "Winterwinde", ["text"] = "Sofort\nIm Schlund oder in Torghast sammeln die Winde jedes Mal, wenn Ihr einen kritischen Treffer erzielt, 13% des Effekts, bis zu einem Höchstwert von 28572 pro kritischem Treffer.\n\nDie Winde werden alle 20 Sek. entfesselt und verursachen Frostschaden in Höhe des insgesamt angesammelten Schadens. Zusätzlich werdet Ihr für 20 Sek. in die Winde gehüllt und absorbiert Schaden in Höhe von 100% des von den Winden verursachten Schadens." }
entries[359395] = { ["name"] = "Blutverbindung", ["text"] = "Sofort\nWenn Ihr einem Gegner im Schlund oder in Torghast Schaden zufügt, entsteht eine 'Blutverbindung'.\n\nDie Blutverbindung pulsiert alle 3 Sek., verursacht dabei 102858 Schattenschaden und heilt Euch um 100% des verursachten Schadens. Anstatt überschüssige Heilung bei Euch hervorzurufen, heilt die Blutverbindung stattdessen einen Verbündeten in der Nähe. Maximal 1 Blutverbindung." }
entries[359396] = { ["name"] = "Chaosbann", ["text"] = "Sofort\nCa. 8 Procs pro Minute\nIm Schlund und in Torghast haben Eure Zauber und Fähigkeiten eine Chance, Eurem Ziel ein Seelenfragment zu entziehen, das Euren Primärwert 30 Sek. lang um 605 erhöht. Bis zu 15-mal stapelbar.\n\nBei Erreichen von 15 Stapeln entfesselt Ihr 'Chaosbann', was 90686 Schattenschaden verursacht, der auf Gegner in der Nähe aufgeteilt wird, und Euren Primärwert 15 Sek. lang um 18137 erhöht.\n(500ms Abklingzeit)" }
entries[359397] = { ["name"] = "Heulender Blizzard" }
entries[359398] = { ["name"] = "Sternenregen" }
entries[359399] = { ["name"] = "Sternenregen", ["text"] = "200 Meter Reichweite\nSofort\nRuft Wellen fallender Sterne auf Gegner innerhalb von 40 Metern herab, die Gegnern im Verlauf von 8 Sek. [9 * (22.4% der Zaubermacht)] Astralschaden zufügen. Mehrfache Anwendungen dieser Fähigkeit können sich überschneiden. [ Ätherischer Zunder : Verlängert die Dauer aktiver Effekte von 'Mondfeuer' und 'Sonnenfeuer' um 3 Sek ]" }
entries[359400] = { ["name"] = "Stachelige Bälle", ["text"] = "Sofort\nDer Leidensschmied lässt stachelige Bälle über den Boden der Kammer rollen, die Spielercharakteren in ihrer Bahn 400 körperlichen Schaden zufügen und sie für 8 Sek. betäuben." }
entries[359401] = { ["name"] = "Genesiskrabbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Jene Erleuchteten, die Tarachniden beobachtet haben, glauben, dass diese Art zu den ersten Wesen gehörte, die durch die Länder von Zereth Mortis streiften.\"\nBeruf:\nProtoformsynthese" }
entries[359402] = { ["name"] = "Tarachnidenkriecher", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese Tarachniden hausen in den finstersten Ecken von Zereth Mortis und verlassen sie nur, um zu jagen (oder um manchmal einen Reiter auf ihrem Rücken zu tragen).\"\nBeruf:\nProtoformsynthese" }
entries[359403] = { ["name"] = "Unergründlicher Krabbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese Tarachniden bewegen sich mit einer Absicht, die niemand nachvollziehen kann, und scheinen nur einem höheren Ruf zu folgen. Was auch immer sich dahinter verbergen mag, es scheint regelmäßige Hilfe für Sterbliche zu beinhalten, die ein Reittier benötigen. Für den Moment zumindest.\"\nBeruf:\nProtoformsynthese" }
entries[359407] = { ["name"] = "Verlustverzerrter Todeswandler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese raue, wirbelnde Energie ist in kohäsiver Form gebunden und unterwirft sich nur dem Willen derjenigen, die stark und entschlossen genug sind, sie zu binden.\"\nErfolg:\nSchlüsselsteinmeister von Shadowlands: Saison 3\nKategorie:\nDungeons" }
entries[359408] = { ["name"] = "Göttlicher Kuss von Ohn'ahra", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei." }
entries[359409] = { ["name"] = "Ottuk des Iskaarahändlers", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Es gibt keine Garantie beim Kauf eines Ottuks von Tattukiaka. Immerhin sind sie niedlich.\"\nVerkäufer:\nTattukiaka\nZone:\nAzurblaues Gebirge\nKosten:\n1\n1" }
