entries[359487] = { ["name"] = "Flammengrifffalle", ["text"] = "Sofort\nDer Leidensschmied sucht sich bis zu 40 Opfer aus und aktiviert nach 38 Sek. eine brennende Falle an ihren Positionen.\n\nDie Fallen explodieren und lösen ' Flammengriffausbruch ' aus, wenn sie von Spielercharakteren, Stacheln oder stacheligen Bällen berührt werden." }
