entries[359490] = { ["name"] = "Massenmahlung - Erste Blume", ["text"] = "Wirken in 2 sek.\nReagenzien:\nErste Blume (20)\nMahlt mehrere Erste Blumen gleichzeitig.\nBeruf:\nInschriftenkunde der Schattenlande (30)\nLehrer:\nSchreiber Au'tehshi\nZone:\nOribos\nKosten:\n1\n15\n\nErste Blume\nHandwerksmaterial\n\"Dieser seltene und wunderschöne Prototyp einer Blume gedeiht im Land der Ersten an tödlichen Orten.\"" }
