entries[359492] = { ["name"] = "Massensondierung von Progenium", ["text"] = "Wirken in 2 sek.\nReagenzien:\nProgeniumerz (20)\nSondiert mehrere Chargen Progeniumerz auf einmal.\nBeruf:\nJuwelierskunst der Schattenlande (40)\nLehrer:\nGutachter Au'vesk\nZone:\nOribos\nKosten:\n2\n\nProgeniumerz\nHandwerksmaterial\n\"Kann aus Ablagerungen und Elementaren gewonnen werden, die man in den schroffsten und gefährlichsten Gegenden von Zereth Mortis findet.\"" }
