entries[360006] = { ["name"] = "Wolke der Fäulnis", ["text"] = "Wirken in 2.5 sek.\nMal'Ganis umgibt das Ziel mit einer Insektenwolke, die ihm alle 1 Sek. 7310 Seuchenschaden zufügt. Die Intensität nimmt mit der Zeit zu.\n\nWenn sich das Ziel einem anderen Spielercharakter bis auf 5 Meter nähert, springen die Insekten auf diesen über und die Intensität wird zurückgesetzt.\n\nBei Entfernung wird das Ziel mit ' Beißende Wunden ' belegt." }
entries[360007] = { ["name"] = "Magisch regulierter Automakern", ["text"] = "Wirken in 1.5 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nEwiger Kristall (5), Progeniumerz , Unsterblichkeitssplitter (5)\nVerkäufer:\nOlea Manu\nZone:\nZereth Mortis\nKosten:\n25\n\nMagisch regulierter Automakern\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Chance durch Fähigkeiten, in Zielnähe Automakern zu erzeugen, der Schaden und Heilung verursacht.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör." }
entries[360008] = { ["name"] = "Wolke der Fäulnis", ["text"] = "150 Meter Reichweite\nSofort\nMal'Ganis umgibt das Ziel mit einer Insektenwolke, die ihm alle 0.5 Sek. 7310 Seuchenschaden zufügt. Die Intensität nimmt mit der Zeit zu.\n\nWenn sich das Ziel einem anderen Spielercharakter bis auf 5 Meter nähert, springen die Insekten auf diesen über, desorientieren ihn für 1 Sek. und die Intensität wird zurückgesetzt.\n\nBei Entfernung wird das Ziel mit ' Beißende Wunden ' belegt." }
entries[360009] = { ["name"] = "Bekannter Himmel", ["text"] = "Auf Kontinenten, die Ihr vollständig erkundet habt, ist die Abklingzeit von 'Segeln' um 1 Min. verringert." }
