entries[360012] = { ["name"] = "Wolke der Fäulnis", ["text"] = "150 Meter Reichweite\nSofort\nMal'Ganis umgibt das Ziel mit einer Insektenwolke, die ihm alle 1 Sek. 7310 Seuchenschaden zufügt. Die Intensität nimmt mit der Zeit zu.\n\nWenn sich das Ziel einem anderen Spielercharakter bis auf 5 Meter nähert, springen die Insekten auf diesen über und die Intensität wird zurückgesetzt.\n\nBei Entfernung wird das Ziel mit ' Beißende Wunden ' belegt." }
entries[360013] = { ["name"] = "Kosmisches Protogewebe", ["text"] = "Wirken in 1.5 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nHeiliger Splitter (10), Seidene Protofaser (6), Unsterblichkeitssplitter (5)\nBeute von:\nSorranos\nZone:\nZereth Mortis\n\nKosmisches Protogewebe\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Erhöht die Vermeidung und beim Erleiden von Schaden besteht eine Chance, dass Ihr geheilt werdet.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör." }
entries[360014] = { ["name"] = "Infusion: Leichenläuterung", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErste Blume (6), Nachtschatten (8), Destilliertes Todesextrakt (5)\nBeute von:\nXy'rath der Begehrliche\nZone:\nZereth Mortis\n\nInfusion: Leichenläuterung\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Chance, dass Ihr Ressourcen erhaltet, wenn Ihr einen Gegner tötet, der Erfahrung oder Ehre gewährt.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör." }
entries[360015] = { ["name"] = "Wolke der Fäulnis", ["text"] = "150 Meter Reichweite\nSofort\nMal'Ganis umgibt das Ziel mit einer Insektenwolke, die ihm alle 1 Sek. 7310 Seuchenschaden zufügt. Die Intensität nimmt mit der Zeit zu.\n\nWenn sich das Ziel einem anderen Spielercharakter bis auf 5 Meter nähert, springen die Insekten auf diesen über und die Intensität wird zurückgesetzt.\n\nBei Entfernung wird das Ziel mit ' Beißende Wunden ' belegt." }
entries[360016] = { ["name"] = "Akkolarischer Harmonisierungsstein", ["text"] = "Wirken in 1.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nProgeniumerz (7), Formbarer Draht (5), Oribrant (5), Umbryl (5)\nBeute von:\nTethos\nZone:\nZereth Mortis\n\nAkkolarischer Harmonisierungsstein\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Chance durch Fähigkeiten, in der Nähe ein Partikel zu erzeugen. Sammelt es für Primärwert (15 Sek.).\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör." }
