entries[360078] = { ["name"] = "Pocopoc beschwören", ["text"] = "Wirken in 1.5 sek. 10 sek. Abklingzeit\nBeschwört Pocopoc, damit er Euch in Zereth Mortis begleitet.\n\nPocopoc kann Euch bei verschiedenen Aufgaben unterstützen, was jedoch Pocopocenergie kostet.\n\nPocopocenergie lädt sich mit der Zeit wieder auf." }
