entries[360148] = { ["name"] = "Schreckensbersten", ["text"] = "150 Meter Reichweite\nSofort\nSchatten brechen um das Ziel aus, was Spielercharaktere innerhalb von 10 Metern 12 Sek. lang furchterfüllt fliehen lässt.\n\nWenn dieser Effekt einen mit ' Wolke der Fäulnis ' belegten Spielercharakter trifft, wird stattdessen der Effekt entfernt, die Insekten lösen sich und fliehen von der Position dieses Spielercharakters." }
