entries[360174] = { ["name"] = "Todesurteil", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Kerkermeister verurteilt einen Spielercharakter zum Tod, was ihm alle 2 Sek. 20 Schattenschaden zufügt und ihn nach Ablauf tötet. Dieser Effekt wird mit der Zeit stärker (30 Sek.).\n\nBei Entfernung entfesselt der Spielercharakter dunkle Energie an Positionen in der Nähe, die getroffene Spielercharaktere mit ' Todesurteil ' belegt. Wenn nicht mindestens ein Spielercharakter von der Energie getroffen wird, werden alle Spielercharaktere mit ' Todesurteil ' belegt.\n\nBei zwei Anwendungen von ' Todesurteil ' sterben Spielercharaktere sofort." }
entries[360175] = { ["name"] = "Todesurteil", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Kerkermeister verurteilt einen Spielercharakter zum Tod, was ihm alle 2 Sek. 20 Schattenschaden zufügt und ihn nach Ablauf tötet. Dieser Effekt wird mit der Zeit stärker (30 Sek.).\n\nBei Entfernung entfesselt der Spielercharakter dunkle Energie an Positionen in der Nähe, die getroffene Spielercharaktere mit ' Todesurteil ' belegt. Wenn nicht mindestens ein Spielercharakter von der Energie getroffen wird, werden alle Spielercharaktere mit ' Todesurteil ' belegt.\n\nBei zwei Anwendungen von ' Todesurteil ' sterben Spielercharaktere sofort." }
