entries[360317] = { ["name"] = "Verschlingeressenzstein", ["text"] = "Wirken in 1.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nProgeniumerz (7), Formbarer Draht (4), Wutauge (8)\nBeute von:\nDer Umhüller und veränderlicher Sternfresser\nZone:\nZereth Mortis\n\nVerschlingeressenzstein\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Wenn Ihr einen Gegner tötet, erhöht sich Euer höchster Sekundärwert für 20 Sek. Bis zu 5-mal stapelbar.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör." }
entries[360318] = { ["name"] = "Pflegende Rüstungspolitur", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErste Blume (6), Todesblüte (25), Destilliertes Todesextrakt (5)\nBeute von:\nZatojin und Schlemmerin\nZone:\nZereth Mortis\n\nPflegende Rüstungspolitur\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Erhöht die Dauer von Effekten durch Fläschchen, Elixiere und Sättigungseffekte um 50%.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör." }
