entries[360417] = { ["name"] = "Infiltration des Schreckens", ["text"] = "Sofort\nBei Erreichen von 100 Energie lässt Kin'tessa beide Schreckenslords die Essenzen von Spielercharakteren mit ' Paranoia ' infiltrieren. Wenn ihre Verkleidungen nicht innerhalb von 35 Sek. gefunden und besiegt werden, brechen sie mit ' Gedankenspaltung ' hervor." }
entries[360418] = { ["name"] = "Paranoia", ["text"] = "Sofort\nWährend die Schreckenslords die Essenzen Sterblicher infiltrieren, können sich die Spielercharaktere gegenseitig nicht trauen und sind ihren Verbündeten gegenüber feindselig gesinnt. Der Aufenthalt in der Nähe eines anderen Spielercharakters gewährt einen Hinweis auf dessen Essenz.\n\nVerursacht alle 1 Sek. 522 Schattenschaden, bis die Verkleidungen der Schreckenslords besiegt wurden." }
